"use strict";exports.id=21899,exports.ids=[21899],exports.modules={21899:a=>{a.exports=JSON.parse('{"_status":"machine-draft, needs human review","Based on your answers, we are connecting you with immediate support. Please reach out for support now. This information is free and always available — no payment, no registration required.":"Deebii keessan irratti hundaa\'uun, deeggarsa hatattamaa waliin isin walqunnamsiisaa jirra. Maaloo amma deeggarsa gaafadhaa. Odeeffannoon kun bilisaa fi yeroo hunda argama — kaffaltiin ykn galmeen hin barbaachisu.","Belonging & Community":"Miseensummaa fi Hawaasa","Biological, Wellbeing and Health":"Baayoloojii, Nageenya Qaamaa fi Fayyaa","If you are in immediate danger, contact local emergency services or go to the nearest health facility now.":"Yoo balaa hatattamaa keessa jirtan, tajaajila balaa tasaa naannoo keessanii qunnamaa ykn amma dhaabbata fayyaa isinitti dhihoo jirutti deemaa.","If you are struggling to meet your basic needs, these services can help. This information is free and always available.":"Yoo fedhii bu\'uuraa keessan guuttachuuf rakkattan, tajaajilli kun isin gargaaruu danda\'a. Odeeffannoon kun bilisaa fi yeroo hunda argama.","Money & Business Reflection":"Yaada Maallaqaa fi Daldalaa","Peace & Harmony":"Nagaa fi Walsimannaa","Relationships & Family":"Hariiroo fi Maatii","Spiritual & Life Direction":"Hafuuraa fi Kallattii Jireenyaa","being reviewed":"gamaaggamamaa jira","consultation requested":"mariin gaafatameera","full report available":"gabaasni guutuun ni argama","high":"olaanaa","not submitted yet":"ammallee hin ergamne","referral advised":"riferaalli gorfameera","report ready":"gabaasni qophaa\'eera","support contacts shared":"qunnamtiiwwan deeggarsaa qoodamaniiru","urgent":"ariifachiisaa","waiting for a reviewer":"gamaaggamaa eegaa jira"}')}};